@StepScope
@Bean
public FlatFileItemWriter<Employee> flatFileItemWriter(
        @Value("#{jobParameters['outputFile']}") FileSystemResource fileResource) {
    return new FlatFileItemWriterBuilder<Employee>()
            .name("employeeItemWriter")
            .resource(fileResource)
            .delimited()
            .delimiter(";")
            .names(new String[] {"empId", "empName", "email", "jobLoc"})
            .build();
}

@Bean
public JsonFileItemWriter<Employee> jsonFileItemWriter(
        @Value("#{jobParameters['outputFile']}") FileSystemResource fileResource) {
    return new JsonFileItemWriter<>(fileResource,
            new JacksonJsonObjectMarshaller<Employee>());
}

@Bean
public JdbcBatchItemWriter<Employee> jdbcBatchItemWriter() {
    return new JdbcBatchItemWriterBuilder<Employee>()
            .dataSource(customDataSource())
            .sql("INSERT INTO employee(empid, empname, email, jobloc) " +
                 "VALUES (:empId, :empName, :email, :jobLoc)")
            .beanMapped() // Maps bean properties to SQL named parameters
            .build();
}

